import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for batched matrix multiplication:
#   C[b,i,j,k] = sum_l A[b,i,j,l] * B[l,k]
#
# Parameters:
#   A : const float*   – pointer to A (shape: Bdim, Idim, Jdim, Kdim)
#   B : const float*   – pointer to B (shape: Kdim, Kdim)  (here B is (l, k))
#   C : float*         – output pointer (shape: Bdim, Idim, Jdim, Kdim)
#   Bdim : int         – number of rows of B (l)
#   Idim : int         – size of A along axis 1 (i)
#   Jdim : int         – size of A along axis 2 (j)
#   Kdim : int         – size of B along axis 1 (k)
# ----------------------------------------------------------------------
custom_mm_kernel_source = """
__global__ void batched_matmul_kernel(const float* A, const float* B, float* C, int Bdim, int Idim, int Jdim, int Kdim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < Bdim * Idim * Jdim * Kdim) {
        int total_per_bikj = Idim * Jdim * Kdim;
        int b = idx / total_per_bikj;
        int rem1 = idx % total_per_bikj;
        int i_val = rem1 / (Jdim * Kdim);
        int rem2 = rem1 % (Jdim * Kdim);
        int j_val = rem2 / Kdim;
        int k_val = rem2 % Kdim;
        float sum = 0.0f;
        for (int l = 0; l < Bdim; ++l) {
            int a_idx = ((b * Idim + i_val) * Jdim + j_val) * Bdim + l;
            int b_idx = l * Kdim + k_val;
            sum += A[a_idx] * B[b_idx];
        }
        C[idx] = sum;
    }
}

torch::Tensor batched_matmul_cuda(float* A, float* B, float* C, int Bdim, int Idim, int Jdim, int Kdim) {
    int total = Bdim * Idim * Jdim * Kdim;
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;
    batched_matmul_kernel<<<num_blocks, block_size>>>(
        A, B, C, Bdim, Idim, Jdim, Kdim);
    return C;
}
"""

# C++ declaration for the function
custom_matmul_cpp_source = (
    "torch::Tensor batched_matmul_cuda(float* A, float* B, float* C, int Bdim, int Idim, int Jdim, int Kdim);"
)

custom_matmul_cuda_source = custom_mm_kernel_source

# Compile the inline CUDA code
custom_matmul = load_inline(
    name="batched_matmul_cuda",
    cpp_sources=custom_matmul_cpp_source,
    cuda_sources=custom_matmul_cuda_source,
    functions=["batched_matmul_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.custom_matmul = custom_matmul

    def forward(self, A, B):
        # A: (b, i, j, l), B: (l, k)
        b, i, j, l = A.shape
        k = B.shape[1]
        # Allocate output tensor of shape (b, i, j, k)
        C = torch.empty((b, i, j, k), dtype=A.dtype, device=A.device)
        A_ptr = A.data_ptr()
        B_ptr = B.data_ptr()
        C_ptr = C.data_ptr()
        # Call the custom function:
        #   A, B, C, Bdim (=l), Idim (=i), Jdim (=j), Kdim (=k)
        C_out = self.custom_matmul(A_ptr, B_ptr, C_ptr, l, i, j, k)
        return C_out
